SELECT L.ID, L.NUNOTA, DATE_FORMAT(L.DT_LANCAMENTO, '%d/%m/%Y') AS DATA, T.NOME AS TIPO_ARMAZENAGEM, CASE WHEN N.ATUALESTOQUE = -1 THEN 'Entrada (Estoque Parceiro)' WHEN N.ATUALESTOQUE = 1 THEN 'Entrada (Nosso Estoque)' ELSE 'Outros' END AS MOVIMENTO, ROUND(IFNULL((SELECT SUM(VALOR_TOTAL_ITEM) FROM ITEM_LANCAMENTO WHERE ID_LANCAMENTO = L.ID), 0), 2) AS VALOR_TOTAL FROM LANCAMENTO_ARMAZENAGEM L JOIN TIPO_ARMAZENAGEM T ON L.ID_TIPO_ARMAZENAGEM = T.ID LEFT JOIN (SELECT NUNOTA, MAX(ATUALESTOQUE) AS ATUALESTOQUE FROM IMP_NOTAS_ARMAZ GROUP BY NUNOTA) N ON L.NUNOTA = N.NUNOTA WHERE L.NUNOTA IS NOT NULL AND L.CODPARC = :VAR_PARCEIRO_SELECIONADO AND DATE_FORMAT(L.DT_LANCAMENTO, '%Y-%m') = :VAR_MES_SELECIONADO ORDER BY L.DT_LANCAMENTO DESC